// @ts-check

/**
 * @typedef {Object} ComputeDayParams
 * @property {number} lat
 * @property {number} lon
 * @property {number} elev
 * @property {string} tz
 * @property {number} y
 * @property {number} m
 * @property {number} d
 */

/**
 * @typedef {Object} EventDescription
 * @property {boolean} occurs
 * @property {string} [note]
 * @property {string} [litTimeStr]
 * @property {number} [litEpochMs]
 * @property {string} [geometricTimeStr]
 * @property {number|null} [correctionSeconds]
 * @property {number} [illumFraction]
 * @property {number} [phaseAngleDeg]
 * @property {number} [thetaDeg]
 * @property {number} [hExact]
 * @property {number} [uncertaintySeconds]
 * @property {boolean} [shallow]
 */

/**
 * @typedef {Object} MoonGlyphOptions
 * @property {number} [size=48]
 * @property {string} [darkFill='#2a2440']
 * @property {string} [litFill='#d8b26a']
 * @property {string} [strokeColor='#6b5a8a']
 * @property {string} [horizonColor='#9c98a8']
 * @property {string} [label='Moon orientation at event']
 */

interface ComputeDayParams {
  lat: number;
  lon: number;
  elev: number;
  tz: string;
  y: number;
  m: number;
  d: number;
}

interface EventDescription {
  occurs: boolean;
  note?: string;
  litTimeStr?: string;
  litEpochMs?: number;
  geometricTimeStr?: string;
  correctionSeconds?: number | null;
  illumFraction?: number;
  phaseAngleDeg?: number;
  thetaDeg?: number;
  hExact?: number;
  uncertaintySeconds?: number;
  shallow?: boolean;
}

interface MoonGlyphOptions {
  size?: number;
  darkFill?: string;
  litFill?: string;
  strokeColor?: string;
  horizonColor?: string;
  label?: string;
}

/**
 * compute.js — pure (no-DOM) computation and rendering-data assembly for the
 * moon.html UI, factored out so it can be exercised headlessly from Node
 * (see test/compute.test.js and the build's own verification) as well as
 * from the browser bundle (src/app.js).
 *
 * `computeDay()` needs an Astronomy Engine module/namespace passed in
 * explicitly (the caller supplies either `import * as Astronomy from
 * 'astronomy-engine'` in Node, or `window.Astronomy` in the browser) so this
 * file itself has no import of astronomy-engine and no reference to
 * `window`/`document` anywhere.
 */

import { createMoonCalc } from './moon-calc.js';
import { zonedMidnight, formatTimeInZone } from './time.js';
import * as AstronomyImp from 'astronomy-engine';

const SECONDS_PER_DAY = 86400;
const THIRTY_SECONDS_DAYS = 30 / SECONDS_PER_DAY;

/**
 * @param {typeof AstronomyImp} Astronomy  Astronomy Engine module/namespace.
 * @param {ComputeDayParams} p
 * @returns {{rise: EventDescription, set: EventDescription}}
 */
export function computeDay(Astronomy: typeof AstronomyImp=AstronomyImp, { lat, lon, elev, tz, y, m, d }: ComputeDayParams): { rise: EventDescription; set: EventDescription; } {
    const calc = createMoonCalc(Astronomy);
    const observer = new Astronomy.Observer(lat, lon, elev);
    const midnight = zonedMidnight(y, m, d, tz);
    const events = calc.moonEventsForDay(midnight, observer, { mode: 'lit' });

    return {
        rise: describeEvent(calc, observer, tz, events.rise),
        set: describeEvent(calc, observer, tz, events.set)
    };
}

/**
 * @param {ReturnType<typeof createMoonCalc>} calc
 * @param {AstronomyImp.Observer} observer
 * @param {string} tz
 * @param {{
 *   lit: AstronomyImp.AstroTime|null,
 *   geometric: AstronomyImp.AstroTime|null,
 *   correctionSeconds: number|null
 * }} ev
 * @returns {EventDescription}
 */
function describeEvent(calc: ReturnType<typeof createMoonCalc>, observer: AstronomyImp.Observer, tz: string, ev: {
        lit: AstronomyImp.AstroTime | null;
        geometric: AstronomyImp.AstroTime | null;
        correctionSeconds: number | null;
    }): EventDescription {
    if (!ev.lit || !ev.geometric) {
        return {
            occurs: false,
            note: 'The Moon’s cycle (~24h50m) is longer than a civil day, so a ' +
                'rise or set occasionally falls outside this calendar day rather ' +
                'than skipping entirely — try the neighboring date.'
        };
    }

    const litTime = ev.lit;
    const geo = calc.moonGeometry(litTime, observer);

    // Timing-precision estimate: the library's stated accuracy is ~1 arcminute
    // in the Moon's position. Convert that to a time uncertainty via the local
    // rate of change of the lit-limb altitude excess, sampled symmetrically
    // 30 s either side of the event (a 1-minute window, so the difference of
    // the two samples is directly the rate in degrees/minute).
    const tPlus = litTime.AddDays(THIRTY_SECONDS_DAYS);
    const tMinus = litTime.AddDays(-THIRTY_SECONDS_DAYS);
    const excessPlus = calc.litLimbAltitudeExcess(tPlus, observer, { mode: 'lit' });
    const excessMinus = calc.litLimbAltitudeExcess(tMinus, observer, { mode: 'lit' });
    const rateDegPerMin = excessPlus - excessMinus;
    const uncertaintySeconds = rateDegPerMin === 0
        ? Infinity
        : Math.abs((1 / 60) / rateDegPerMin * 60);

    return {
        occurs: true,
        litTimeStr: formatTimeInZone(litTime.date, tz, { seconds: true }),
        litEpochMs: litTime.date.getTime(),
        geometricTimeStr: formatTimeInZone(ev.geometric.date, tz, { seconds: true }),
        correctionSeconds: ev.correctionSeconds,
        illumFraction: geo.litFraction,
        phaseAngleDeg: geo.phaseAngleDeg,
        thetaDeg: geo.thetaDeg,
        hExact: geo.hExact,
        uncertaintySeconds,
        shallow: !(uncertaintySeconds <= 60)
    };
}

/**
 * A plain-words gloss of a signed correction in seconds, for the "secondary"
 * line of a result card.
 * @param {'rise'|'set'} which
 * @param {number} correctionSeconds  lit − geometric, seconds.
 * @returns {string}
 */
export function correctionGloss(which: 'rise' | 'set', correctionSeconds: number): string {
    const verb = which === 'rise' ? 'rises' : 'sets';
    const mag = Math.abs(correctionSeconds).toFixed(1);
    if (Math.abs(correctionSeconds) < 0.05) {
        return `lit part ${verb} at essentially the same moment`;
    }
    const dir = correctionSeconds < 0 ? 'earlier' : 'later';
    return `lit part ${verb} ${mag} s ${dir}`;
}

// ------------------------------------------------------------ orientation SVG

/**
 * Boundary of the projected lit region of the disk, sampled in polar form
 * around the same (x = horizontal, y = up) sky frame lit-limb.js uses, at
 * `samples` angles psi in [0, 2*pi). Reuses exactly the per-direction lit
 * interval math src/lit-limb.js's litDiskAreas() integrates over (the
 * candidate "a, phi, litLo, litHi" derivation there), just returning the
 * boundary points themselves instead of an integrated area, so a crescent's
 * dark centre and a gibbous's simple bulge both come out correctly instead of
 * approximating with a single ellipse.
 *
 * @param {number} thetaDeg
 * @param {number} phaseAngleDeg
 * @param {number} [samples=96]
 * @returns {{outer: [number,number][], inner: [number,number][]}} unit-disk
 *   (x, y) points, up positive. `inner` is all zeros except near a crescent's
 *   cusps, where the lit sliver does not reach the disk centre.
 */
function litRegionBoundary(thetaDeg: number, phaseAngleDeg: number, samples: number = 96): { outer: [number, number][]; inner: [number, number][]; } {
    const DEG = Math.PI / 180;
    const th = thetaDeg * DEG;
    const i = phaseAngleDeg * DEG;
    const sinI = Math.sin(i);
    const cosI = Math.cos(i);
    const HALF_PI = Math.PI / 2;

    const outer = [];
    const inner = [];
    for (let k = 0; k < samples; k++) {
        const psi = (k / samples) * 2 * Math.PI;
        const a = sinI * Math.sin(psi + th);
        const phi = Math.atan2(cosI, a);
        let litLo = Math.max(0, -phi);
        let litHi = Math.min(HALF_PI, Math.PI - phi);
        if (litHi <= litLo) { litLo = 0; litHi = 0; }
        const rOuter = Math.sin(litHi);
        const rInner = Math.sin(litLo);
        outer.push([rOuter * Math.cos(psi), rOuter * Math.sin(psi)]);
        inner.push([rInner * Math.cos(psi), rInner * Math.sin(psi)]);
    }
    return { outer, inner };
}

/**
 * @param {number} thetaDeg
 * @param {number} phaseAngleDeg
 * @param {MoonGlyphOptions} [opts]
 * @returns {string} a self-contained `<svg>...</svg>` string.
 */
export function moonGlyphSvg(thetaDeg: number, phaseAngleDeg: number, opts: MoonGlyphOptions = {}): string {
    const size = opts.size ?? 48;
    const darkFill = opts.darkFill ?? '#2a2440';
    const litFill = opts.litFill ?? '#d8b26a';
    const strokeColor = opts.strokeColor ?? '#6b5a8a';
    const horizonColor = opts.horizonColor ?? '#9c98a8';
    const label = opts.label ?? 'Moon orientation at event';

    const r = size * 0.32;
    const cx = size / 2;
    const cy = size * 0.42;

    const { outer, inner } = litRegionBoundary(thetaDeg, phaseAngleDeg);
    const toScreen = ([x, y]) => `${(cx + x * r).toFixed(2)},${(cy - y * r).toFixed(2)}`;
    const litPathD = `M ${outer.map(toScreen).join(' L ')} Z M ${inner.map(toScreen).join(' L ')} Z`;

    const horizonY = (cy + r + 4).toFixed(2);

    return `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" ` +
        `xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${label}">` +
        `<circle cx="${cx}" cy="${cy}" r="${r.toFixed(2)}" fill="${darkFill}" stroke="${strokeColor}" stroke-width="1"/>` +
        `<path d="${litPathD}" fill="${litFill}" fill-rule="evenodd"/>` +
        `<line x1="1" y1="${horizonY}" x2="${size - 1}" y2="${horizonY}" stroke="${horizonColor}" stroke-width="1.5"/>` +
        `</svg>`;
}
