// @ts-check

/**
 * lit-limb.js — pure geometry of the Moon's illuminated limb.
 *
 * NO dependency on Astronomy Engine (or on anything else). Everything here is
 * plain trigonometry so it can be unit-tested in isolation and reused in the
 * browser bundle.
 *
 * UNITS
 * -----
 * Unless a parameter name says otherwise, **angles are in degrees, in and out**.
 * The single exception is right ascension, which is taken in **hours**
 * (0..24) because that is what `Astronomy.Equator()` returns, and converting at
 * every call site is the kind of thing that eventually gets forgotten.
 * `brightLimbPositionAngleFromDegrees()` is provided for callers that already
 * hold RA in degrees.
 *
 * SKY FRAME used by the h / lit-area functions
 * --------------------------------------------
 * A flat disk of unit radius, centred on the Moon's centre, with
 *   +y = towards the observer's zenith ("up"),
 *   +x = horizontal (which horizontal direction is deliberately unspecified —
 *        every quantity computed here is invariant under the mirror x -> -x).
 * The bright limb points along b = (sin θ, cos θ), i.e. θ is measured from the
 * vertical, positive towards +x. θ = 0 => bright limb straight up,
 * θ = 180 => bright limb straight down.
 */

const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

/**
 * Normalise an angle in degrees to the half-open interval (-180, +180].
 * @param {number} deg
 * @returns {number}
 */
export function normalizeAngle180(deg: number): number {
    let a = deg % 360;
    if (a <= -180) a += 360;
    if (a > 180) a -= 360;
    // guard against -180 surviving a float wobble
    if (a <= -180) a += 360;
    return a;
}

/**
 * Position angle of the Moon's bright limb — Meeus, *Astronomical Algorithms*,
 * 2nd ed., formula 48.5:
 *
 *   tan χ = cos δ0 · sin(α0 − α)
 *           ---------------------------------------------------
 *           sin δ0 · cos δ − cos δ0 · sin δ · cos(α0 − α)
 *
 * where (α0, δ0) is the Sun and (α, δ) is the Moon. χ is a position angle
 * measured on the sky from the north celestial pole, counter-clockwise
 * (i.e. north through east). It points from the Moon's centre towards the
 * midpoint of the illuminated limb — equivalently, it is the sky-projected
 * direction from the Moon towards the Sun.
 *
 * Feed it TOPOCENTRIC apparent coordinates (same equinox for both bodies) when
 * you care about what an observer on the ground sees.
 *
 * @param {number} raSunHours   Sun right ascension α0, in HOURS.
 * @param {number} decSunDeg    Sun declination δ0, in degrees.
 * @param {number} raMoonHours  Moon right ascension α, in HOURS.
 * @param {number} decMoonDeg   Moon declination δ, in degrees.
 * @returns {number} χ in degrees, normalised to (-180, +180].
 */
export function brightLimbPositionAngle(raSunHours: number, decSunDeg: number, raMoonHours: number, decMoonDeg: number): number {
    const dAlpha = (raSunHours - raMoonHours) * 15 * DEG; // α0 − α, radians
    const d0 = decSunDeg * DEG;
    const d = decMoonDeg * DEG;
    const y = Math.cos(d0) * Math.sin(dAlpha);
    const x = Math.sin(d0) * Math.cos(d) - Math.cos(d0) * Math.sin(d) * Math.cos(dAlpha);
    return normalizeAngle180(RAD * Math.atan2(y, x));
}

/**
 * Same as {@link brightLimbPositionAngle} but with right ascensions in degrees.
 * @param {number} raSunDeg
 * @param {number} decSunDeg
 * @param {number} raMoonDeg
 * @param {number} decMoonDeg
 * @returns {number} χ in degrees.
 */
export function brightLimbPositionAngleFromDegrees(raSunDeg: number, decSunDeg: number, raMoonDeg: number, decMoonDeg: number): number {
    return brightLimbPositionAngle(raSunDeg / 15, decSunDeg, raMoonDeg / 15, decMoonDeg);
}

/**
 * Parallactic angle — Meeus formula 14.1:
 *
 *   tan q = sin H / (tan φ · cos δ − sin δ · cos H)
 *
 * NOTE the second term is sin **δ**, not sin φ. This is just the position angle
 * of the zenith in the spherical triangle (pole, body, zenith): the zenith has
 * declination φ and hour angle 0, so its RA differs from the body's by exactly
 * H, and the standard position-angle formula gives
 *   tan q = sin H·cos φ / (cos δ·sin φ − sin δ·cos φ·cos H),
 * which divided through by cos φ is the line above.
 *
 * q is the position angle of the observer's zenith as seen at the body,
 * measured from the north celestial pole in the same sense as χ (north through
 * east). It is zero on the meridian (for a body south of the zenith), positive
 * west of the meridian.
 *
 * φ must be the observer's GEODETIC latitude: the local vertical is by
 * definition the direction whose declination equals the geodetic latitude, and
 * that is the direction this formula rotates towards. δ and H should be the
 * body's topocentric apparent declination and local hour angle.
 *
 * @param {number} hourAngleDeg  Local hour angle H in degrees (15° per hour,
 *                               positive west of the meridian; any 360° wrap
 *                               is fine).
 * @param {number} latDeg        Observer geodetic latitude φ, degrees.
 * @param {number} decDeg        Body declination δ, degrees.
 * @returns {number} q in degrees, normalised to (-180, +180].
 */
export function parallacticAngle(hourAngleDeg: number, latDeg: number, decDeg: number): number {
    const H = hourAngleDeg * DEG;
    const phi = latDeg * DEG;
    const dec = decDeg * DEG;
    const y = Math.sin(H);
    const x = Math.tan(phi) * Math.cos(dec) - Math.sin(dec) * Math.cos(H);
    return normalizeAngle180(RAD * Math.atan2(y, x));
}

/**
 * Angle of the bright limb from the local vertical (Meeus ch. 48): θ = χ − q.
 *
 * Both χ and q are position angles reckoned from the celestial north pole in
 * the same rotational sense, so their difference is the angle of the bright
 * limb measured from the zenith direction. θ = 0 means the bright limb points
 * straight up; θ = ±180 means it points straight down.
 *
 * @param {number} chi  χ in degrees.
 * @param {number} q    q in degrees.
 * @returns {number} θ in degrees, normalised to (-180, +180].
 */
export function limbAngleFromVertical(chi: number, q: number): number {
    return normalizeAngle180(chi - q);
}

/**
 * Height of the highest sunlit point of the lunar disk above the disk centre,
 * in units of the apparent semi-diameter (so h ∈ [0, 1]).
 *
 * Derivation (flat-disk / orthographic model). Put the disk in the sky frame
 * described at the top of this file and let i be the phase angle. A point of
 * the lunar surface has unit normal n; write n in the orthonormal frame
 * (e1, e2, e3) where e3 points from the Moon towards the observer and e1 is the
 * in-sky direction towards the Sun, so that the solar direction is
 * s = cos i · e3 + sin i · e1. The terminator is n·s = 0, and the visible
 * hemisphere is n·e3 > 0. Parametrising the visible terminator by t ∈ [0, 1]
 * gives n = t(−cos i · e1 + sin i · e3) ± sqrt(1 − t²) · e2, whose projected
 * height is
 *
 *     H(t) = −t · cos i · cos θ + sqrt(1 − t²) · |sin θ|.
 *
 * Maximising over t ∈ [0, 1]:
 *   • the unconstrained maximum sqrt(cos²i·cos²θ + sin²θ) needs
 *     t* = −cos i·cos θ / h ≥ 0, i.e. cos i · cos θ ≤ 0;
 *   • otherwise the maximum is at the endpoint t = 0, height |sin θ|
 *     (the cusp where the terminator meets the limb).
 * And when cos θ ≥ 0 the top of the disk itself is lit (its n·s = sin i·cos θ
 * ≥ 0), so h = 1 and the highest lit point is on the bright limb.
 *
 * That reproduces the table in PLAN.md:
 *   cos θ ≥ 0                  -> 1
 *   cos θ < 0 and i ≤ 90°      -> sqrt(sin²θ + cos²i · cos²θ)   (gibbous, terminator)
 *   cos θ < 0 and i > 90°      -> |sin θ|                        (crescent, upper cusp)
 *
 * Note the result depends on θ only through cos θ and |sin θ|, so it is
 * invariant under θ -> −θ: the handedness of the sky frame does not matter.
 *
 * @param {number} thetaDeg        θ, degrees (angle of bright limb from vertical).
 * @param {number} phaseAngleDeg   i, degrees (0 = full, 180 = new).
 * @returns {number} h in [0, 1].
 */
export function highestLitPointFactor(thetaDeg: number, phaseAngleDeg: number): number {
    const th = thetaDeg * DEG;
    const i = phaseAngleDeg * DEG;
    const cosTh = Math.cos(th);
    const sinTh = Math.sin(th);
    if (cosTh >= 0) return 1;
    if (phaseAngleDeg <= 90) {
        const cosI = Math.cos(i);
        return Math.sqrt(sinTh * sinTh + cosI * cosI * cosTh * cosTh);
    }
    return Math.abs(sinTh);
}

/**
 * Fraction of the lunar disk's area that is sunlit: (1 + cos i) / 2.
 * @param {number} phaseAngleDeg i, degrees.
 * @returns {number}
 */
export function litDiskAreaFraction(phaseAngleDeg: number): number {
    return (1 + Math.cos(phaseAngleDeg * DEG)) / 2;
}

/**
 * Areas of the sunlit part of the apparent lunar disk, in units where the whole
 * disk has area π.
 *
 * A point p = (x, y) of the unit disk (|p| ≤ 1, +y = up) is sunlit iff
 *
 *     sin i · (p · b) + cos i · sqrt(1 − |p|²) > 0,      b = (sin θ, cos θ)
 *
 * which is just n·s > 0 written in projected coordinates.
 *
 * The integration is done on the visible hemisphere rather than on the flat
 * disk: with n = (sin ξ cos ψ, sin ξ sin ψ, cos ξ) the projected point is
 * p = (sin ξ cos ψ, sin ξ sin ψ), sqrt(1 − |p|²) = cos ξ, and the disk area
 * element is sin ξ cos ξ dξ dψ. For a fixed ψ BOTH constraints — "sunlit" and
 * "above the line y = c" — reduce to a single interval in ξ, and the ξ integral
 * ∫ sin ξ cos ξ dξ = ½ sin²ξ is exact. So only the ψ integral is discretised,
 * which makes this far more accurate than a Cartesian grid for the same cost.
 *
 * @param {number} thetaDeg      θ, degrees.
 * @param {number} phaseAngleDeg i, degrees.
 * @param {number} c             Signed height of the horizontal line, in disk
 *                               radii, −1 (bottom) .. +1 (top), up positive.
 * @param {number} [steps=36000] Number of ψ samples (midpoint rule).
 * @returns {{litArea: number, litAreaAbove: number, diskArea: number}}
 */
export function litDiskAreas(thetaDeg: number, phaseAngleDeg: number, c: number, steps: number = 36000): { litArea: number; litAreaAbove: number; diskArea: number; } {
    const th = thetaDeg * DEG;
    const i = phaseAngleDeg * DEG;
    const sinI = Math.sin(i);
    const cosI = Math.cos(i);
    const HALF_PI = Math.PI / 2;

    let sumAll = 0;   // lit area, any height
    let sumAbove = 0; // lit area above the line
    const dpsi = (2 * Math.PI) / steps;

    for (let k = 0; k < steps; k++) {
        const psi = (k + 0.5) * dpsi;
        const sinPsi = Math.sin(psi);

        // --- sunlit constraint: a·sin ξ + cos i·cos ξ > 0, a = sin i·sin(ψ+θ)
        const a = sinI * Math.sin(psi + th);
        const phi = Math.atan2(cosI, a);           // in (-π, π]
        // a sinξ + C cosξ = K sin(ξ + phi) > 0  <=>  ξ ∈ (-phi, π - phi)
        let litLo = Math.max(0, -phi);
        let litHi = Math.min(HALF_PI, Math.PI - phi);
        if (litHi <= litLo) continue;

        // --- full-disk lit area contribution
        sumAll += 0.5 * (Math.sin(litHi) ** 2 - Math.sin(litLo) ** 2);

        // --- "above the line" constraint: sin ξ · sin ψ > c
        let hiLo = 0, hiHi = HALF_PI;
        if (Math.abs(sinPsi) < 1e-15) {
            if (!(0 > c)) continue;
        } else if (sinPsi > 0) {
            const m = c / sinPsi;
            if (m >= 1) continue;
            if (m > 0) hiLo = Math.asin(m);
        } else {
            const m = c / sinPsi;
            if (m <= 0) continue;
            if (m < 1) hiHi = Math.asin(m);
        }

        const lo = Math.max(litLo, hiLo);
        const hi = Math.min(litHi, hiHi);
        if (hi > lo) {
            sumAbove += 0.5 * (Math.sin(hi) ** 2 - Math.sin(lo) ** 2);
        }
    }

    return {
        litArea: sumAll * dpsi,
        litAreaAbove: sumAbove * dpsi,
        diskArea: Math.PI
    };
}

/**
 * Fraction of the *lit* disk area that lies above a horizontal line at signed
 * height c (in disk radii, −1..+1, up positive).
 *
 * This is the hook for Daniel Glauberman's future "enough light to have hanaah
 * from it" threshold: at a given instant, c = (horizonTarget − altCenter) /
 * semiDiameter puts the line on the horizon, and this returns how much of the
 * illuminated crescent/gibbous is above it. It is NOT used by the rise/set
 * root-find, which only needs the zero crossing of the highest lit point.
 *
 * Sanity: ≈1 at c = −1 (exactly 1 by construction), ≈0 at c = +1 (exactly 0),
 * monotonically decreasing in between.
 *
 * @param {number} thetaDeg      θ, degrees.
 * @param {number} phaseAngleDeg i, degrees.
 * @param {number} c             Line height in disk radii.
 * @param {number} [steps=36000] ψ samples.
 * @returns {number} fraction in [0, 1]; 0 when nothing is lit (i = 180°).
 */
export function litFractionAboveLine(thetaDeg: number, phaseAngleDeg: number, c: number, steps: number = 36000): number {
    const { litArea, litAreaAbove } = litDiskAreas(thetaDeg, phaseAngleDeg, c, steps);
    if (litArea <= 0) return 0;
    return litAreaAbove / litArea;
}

/** R_moon / (1 AU): the Moon's angular radius as seen from the Sun, in radians. */
export const MOON_RADIUS_OVER_AU = 1738.1 / 1.4959787069098932e8;

/**
 * Finite-disk-exact version of {@link highestLitPointFactor}.
 *
 * `highestLitPointFactor()` is the flat-disk / orthographic closed form of
 * PLAN.md. It is a very good approximation but it makes two idealisations that
 * the numerical oracle in test/oracle.test.js can see:
 *
 *  1. **Where the limb is.** The visible part of the Moon is not a hemisphere:
 *     a surface point is visible only if n·ê3 > sin ρ, where ê3 points from the
 *     Moon to the observer and ρ is the apparent semi-diameter. The cusps of a
 *     crescent therefore sit at n·ê3 = sin ρ, not at n·ê3 = 0. For a thin
 *     crescent the cusp parameter is t = sin ρ / sin i, which blows up as
 *     i -> 180°, and the flat model over-estimates the cusp height by up to
 *     ~30 arcseconds near new moon.
 *  2. **Perspective.** The projection from a finite distance is not
 *     orthographic: a point at n·ê3 = c projects to an angular offset
 *     atan(sin ρ·sqrt(1−c²) / (1 − sin ρ·c)), i.e. near-side points are
 *     magnified by a factor (1 + c·sin ρ). For the gibbous branch the maximum
 *     sits at c = sin i·cos i·|cos θ| / h, up to 0.5, which is worth a couple of
 *     arcseconds.
 *
 * It also uses the exact terminator (n·ŝ > R/D rather than n·ŝ > 0), which is
 * worth about 0.01″ and is included only because it is free.
 *
 * Derivation. In the frame (e1, e2, e3) of {@link highestLitPointFactor}, write
 * a surface normal as n = a·e1 + b·e2 + c·e3 and let w = cos θ·e1 + sin θ·e2 be
 * the sky "up" direction, so the projected height is proportional to n·w. The
 * maximum of the height over the sunlit visible region lies on that region's
 * boundary, which has two pieces:
 *
 *  (A) the sunlit part of the limb, c = sin ρ, where n·w = r·cos(β − θ) with
 *      r = sqrt(1 − sin²ρ), and "sunlit" restricts cos β > m =
 *      (εs − sin ρ·cos i)/(r·sin i). Maximum r·1 if |θ| ≤ acos(m), else
 *      r·cos(acos(m) − |θ|) — the cusp.
 *  (B) the terminator n·ŝ = εs, whose unconstrained maximum of n·w is
 *      εs·sin i·cos θ + sqrt(1−εs²)·sqrt(1 − sin²i·cos²θ)
 *      attained at c = εs·cos i − sqrt(1−εs²)·sin i·cos i·cos θ /
 *      sqrt(1 − sin²i·cos²θ); it counts only when that c exceeds sin ρ,
 *      otherwise the terminator maximum is the cusp already covered by (A).
 *
 * Each candidate is then converted to an actual height in degrees with the
 * perspective formula above and the larger one wins. Setting ρ = 0 and εs = 0
 * recovers {@link highestLitPointFactor} exactly.
 *
 * @param {number} thetaDeg         θ, degrees.
 * @param {number} phaseAngleDeg    i, degrees.
 * @param {number} semiDiameterDeg  ρ = asin(R_moon / topocentric distance), degrees.
 * @param {number} [epsSun]         R_moon / (Moon–Sun distance), radians.
 * @returns {number} h such that (height of highest sunlit visible point above
 *   the disk centre) = h · semiDiameterDeg. Returns 0 when nothing sunlit is
 *   visible at all (only within ~ρ of exact new moon).
 */
export function highestLitPointFactor3D(thetaDeg: number, phaseAngleDeg: number, semiDiameterDeg: number,
                                        epsSun: number = MOON_RADIUS_OVER_AU): number {
    if (!(semiDiameterDeg > 0)) return highestLitPointFactor(thetaDeg, phaseAngleDeg);
    const rho = semiDiameterDeg * DEG;
    const sinRho = Math.sin(rho);
    const th = thetaDeg * DEG;
    const i = phaseAngleDeg * DEG;
    const cosTh = Math.cos(th);
    const sinI = Math.sin(i), cosI = Math.cos(i);
    const es = epsSun;
    const rLimb = Math.sqrt(Math.max(0, 1 - sinRho * sinRho));

    // Height in degrees of a surface point with n·w = nw and n·e3 = c.
    const heightDeg = (/** @type {number} */ nw: number, /** @type {number} */ c: number) => {
        const r = Math.sqrt(Math.max(0, 1 - c * c));
        if (r <= 0) return 0;
        return RAD * Math.atan(sinRho * r / (1 - sinRho * c)) * (nw / r);
    };

    let best = -Infinity;

    // (A) sunlit part of the limb, including the cusp.
    const denomA = rLimb * sinI;
    const numA = es - sinRho * cosI;
    const m = (denomA > 0) ? (numA / denomA) : (numA > 0 ? Infinity : -Infinity);
    if (m < 1) {
        const beta0 = (m <= -1) ? Math.PI : Math.acos(m);
        const absTh = Math.abs(th);
        const cosBest = (absTh <= beta0) ? 1 : Math.cos(beta0 - absTh);
        best = Math.max(best, heightDeg(rLimb * cosBest, sinRho));
    }

    // (B) interior maximum on the terminator, when it is on the visible side.
    const root = Math.sqrt(Math.max(0, 1 - sinI * sinI * cosTh * cosTh));
    const sq = Math.sqrt(Math.max(0, 1 - es * es));
    if (root > 0) {
        const cT = es * cosI - sq * sinI * cosI * cosTh / root;
        if (cT > sinRho) {
            best = Math.max(best, heightDeg(es * sinI * cosTh + sq * root, cT));
        }
    }

    if (best === -Infinity) return 0;
    return best / semiDiameterDeg;
}
