// @ts-check

// Timezone-aware day-boundary and formatting primitives.
//
// All rise/set search and display must happen in the *location's* IANA zone,
// never the browser/host zone — see PLAN.md step 2. This module has no
// dependency beyond the platform Intl object, and runs in Node 20+ and in
// browsers.

/**
 * @param {number} n
 */
function pad2(n: number) {
  return String(n).padStart(2, '0');
}

// Parses the 'shortOffset' timeZoneName Intl produces, e.g. 'GMT', 'GMT+2',
// 'GMT+5:30', 'GMT-8', 'GMT+13:45'. Returns the offset in minutes east of UTC.
/**
 * @param {string} text
 */
function parseGmtOffset(text: string) {
  const m = /^GMT(?:([+-])(\d{1,2})(?::(\d{2}))?)?$/.exec(text);
  if (!m) {
    throw new Error(`Unrecognized timezone offset format: ${text}`);
  }
  const [, sign, hh, mm] = m;
  if (!sign) return 0; // plain 'GMT'
  const minutes = Number(hh) * 60 + (mm ? Number(mm) : 0);
  return sign === '-' ? -minutes : minutes;
}

/**
 * UTC offset, in minutes east of UTC, of IANA zone `tz` at instant `date`.
 * @param {Date} date
 * @param {string} tz IANA zone name, e.g. 'Asia/Jerusalem'
 * @returns {number}
 */
export function zoneOffsetMinutes(date: Date, tz: string): number {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    timeZoneName: 'shortOffset',
  }).formatToParts(date);
  const part = parts.find((p) => p.type === 'timeZoneName');
  if (!part) {
    throw new Error(`Could not resolve offset for zone: ${tz}`);
  }
  return parseGmtOffset(part.value);
}

/**
 * The civil (calendar/clock) date and time that instant `date` reads as in
 * zone `tz`.
 * @param {Date} date
 * @param {string} tz
 * @returns {{y:number, m:number, d:number, hh:number, mm:number, ss:number}}
 */
export function civilDateInZone(date: Date, tz: string): { y: number; m: number; d: number; hh: number; mm: number; ss: number; } {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
  const parts = {};
  for (const p of dtf.formatToParts(date)) {
    parts[p.type] = p.value;
  }
  return {
    y: Number(parts.year),
    m: Number(parts.month),
    d: Number(parts.day),
    hh: Number(parts.hour),
    mm: Number(parts.minute),
    ss: Number(parts.second),
  };
}

/**
 * The instant (Date) at which the wall clock in zone `tz` reads
 * (y, m, d, hh, mm, ss). Correct across DST transitions: iterates by
 * guessing an offset, converting, and re-checking the offset at the guessed
 * instant until it stops moving.
 * @param {number} y
 * @param {number} m 1-12
 * @param {number} d
 * @param {number} hh
 * @param {number} mm
 * @param {number} ss
 * @param {string} tz
 * @returns {Date}
 */
export function zonedDateTime(y: number, m: number, d: number, hh: number, mm: number, ss: number, tz: string): Date {
  const wallUtcMs = Date.UTC(y, m - 1, d, hh, mm, ss);
  let offset = 0;
  // A handful of iterations is enough to converge even across a DST edge;
  // offsets only take a small, finite set of values for any real zone.
  for (let i = 0; i < 5; i++) {
    const guess = new Date(wallUtcMs - offset * 60000);
    const nextOffset = zoneOffsetMinutes(guess, tz);
    if (nextOffset === offset) {
      return guess;
    }
    offset = nextOffset;
  }
  return new Date(wallUtcMs - offset * 60000);
}

/**
 * The instant of 00:00:00 local civil time on (y, m, d) in zone `tz`.
 * @param {number} y
 * @param {number} m 1-12
 * @param {number} d
 * @param {string} tz
 * @returns {Date}
 */
export function zonedMidnight(y: number, m: number, d: number, tz: string): Date {
  return zonedDateTime(y, m, d, 0, 0, 0, tz);
}

/**
 * Formats an instant as 'HH:MM' (default) or 'HH:MM:SS' (opts.seconds),
 * 24-hour, in zone `tz`.
 * @param {Date} date
 * @param {string} tz
 * @param {{seconds?: boolean}} [opts]
 * @returns {string}
 */
export function formatTimeInZone(date: Date, tz: string, opts: { seconds?: boolean; } = {}): string {
  const c = civilDateInZone(date, tz);
  const base = `${pad2(c.hh)}:${pad2(c.mm)}`;
  return opts.seconds ? `${base}:${pad2(c.ss)}` : base;
}

/**
 * Formats an instant as 'YYYY-MM-DD HH:MM' (or 'HH:MM:SS' with
 * opts.seconds), 24-hour, in zone `tz`.
 * @param {Date} date
 * @param {string} tz
 * @param {{seconds?: boolean}} [opts]
 * @returns {string}
 */
export function formatDateTimeInZone(date: Date, tz: string, opts: { seconds?: boolean; } = {}): string {
  const c = civilDateInZone(date, tz);
  const datePart = `${c.y}-${pad2(c.m)}-${pad2(c.d)}`;
  return `${datePart} ${formatTimeInZone(date, tz, opts)}`;
}

// Calendar-only day roll: normalizes overflowed/underflowed day-of-month via
// UTC Date arithmetic (a plain calendar computation, not zone-aware — the
// instant returned by zonedMidnight below is what makes the result correct
// for the target zone).
/**
 * @param {number} y
 * @param {number} m
 * @param {number} d
 * @param {number} deltaDays
 */
function addCivilDays(y: number, m: number, d: number, deltaDays: number) {
  const dt = new Date(Date.UTC(y, m - 1, d + deltaDays));
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

/**
 * The [start, end) instant range covering civil date (y, m, d) in zone `tz`.
 * `end` is computed as zonedMidnight of the *next calendar date*, not
 * start + 24h, so DST days that are 23h or 25h long come out right.
 * @param {number} y
 * @param {number} m 1-12
 * @param {number} d
 * @param {string} tz
 * @returns {[Date, Date]}
 */
export function zonedDayRange(y: number, m: number, d: number, tz: string): [Date, Date] {
  const start = zonedMidnight(y, m, d, tz);
  const next = addCivilDays(y, m, d, 1);
  const end = zonedMidnight(next.y, next.m, next.d, tz);
  return [start, end];
}
