// @ts-check

import type { AstroTime, Observer } from 'astronomy-engine';
import * as AstronomyImp from 'astronomy-engine';

type FlexibleDateTime = Date | number | AstroTime;

type HorizonTarget = (
  observer: Observer,
  metersAboveGround: number,
) => number;

interface LitLimbAltitudeExcessOptions {
  mode?: 'lit' | 'lit-flat' | 'geometric';
  metersAboveGround?: number;
  horizonTarget?: HorizonTarget;
}

interface NextMoonEventOptions {
  mode?: 'lit' | 'lit-flat' | 'geometric';
  limitDays?: number;
  metersAboveGround?: number;
  horizonTarget?: HorizonTarget;
}

interface MoonEventsForDayOptions {
  mode?: 'lit' | 'lit-flat';
  metersAboveGround?: number;
  horizonTarget?: HorizonTarget;
}

interface MoonGeometry {
  time: AstroTime;
  altCenterDeg: number;
  azDeg: number;
  distTopoKm: number;
  semiDiameterDeg: number;
  raMoonHours: number;
  decMoonDeg: number;
  hourAngleDeg: number;
  phaseAngleDeg: number;
  phaseAngleGeoDeg: number;
  chiDeg: number;
  qDeg: number;
  thetaDeg: number;
  h: number;
  hExact: number;
  litFraction: number;
  litFractionGeo: number;
}

interface MoonEventTimes {
  lit: AstroTime | null;
  geometric: AstroTime | null;
  correctionSeconds: number | null;
}

interface MoonEventsForDay {
  rise: MoonEventTimes;
  set: MoonEventTimes;
}

/**
 * moon-calc.js — rise/set of the Moon's highest SUNLIT point.
 *
 * Exported as a factory so the same source works in Node (npm
 * `astronomy-engine`) and in the browser (the vendored bundle's global
 * `window.Astronomy`):
 *
 *     import * as Astronomy from 'astronomy-engine';
 *     const calc = createMoonCalc(Astronomy);
 *
 * The "geometric" mode of every function here reproduces Astronomy Engine's own
 * `SearchRiseSet(Body.Moon, ...)` — same horizon target, same unrefracted
 * topocentric altitude, same bracketing, same 0.1 s root tolerance — so that
 * the only difference between the two modes is the h factor from lit-limb.js.
 */

import {
    brightLimbPositionAngle,
    parallacticAngle,
    limbAngleFromVertical,
    highestLitPointFactor,
    highestLitPointFactor3D,
    litDiskAreaFraction,
    litFractionAboveLine
} from './lit-limb.js';

// --- constants copied from astronomy.js (they are not exported by the library)
const MOON_EQUATORIAL_RADIUS_KM = 1738.1;
const REFRACTION_NEAR_HORIZON = 34 / 60;     // degrees
const EARTH_FLATTENING = 0.996647180302104;
const EARTH_EQUATORIAL_RADIUS_KM = 6378.1366;
const SOLAR_DAYS_PER_SIDEREAL_DAY = 0.9972695717592592;
const SECONDS_PER_DAY = 86400;

/** Time step used to bracket rise/set events: same value the library uses. */
const RISE_SET_DT = 0.42;   // days = 10.08 h, Nyquist-safe for the Moon's ~22 h above/below cycle

const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;

/**
 * @param {typeof AstronomyImp} Astronomy  The Astronomy Engine module/namespace object.
 */
export function createMoonCalc(Astronomy: typeof AstronomyImp=AstronomyImp) {
    const Body = Astronomy.Body;
    const MOON_RADIUS_AU = MOON_EQUATORIAL_RADIUS_KM / Astronomy.KM_PER_AU;

    // ---------------------------------------------------------------- horizon

    /**
     * Angular dip of the visible horizon below the observer's horizontal plane,
     * in degrees (<= 0). Verbatim re-implementation of astronomy.js's private
     * `HorizonDipAngle()`, including the Sweer (1938) tangent-ray refraction
     * index, because the library does not export it.
     *
     * @param {Astronomy.Observer} observer
     * @param {number} metersAboveGround
     * @returns {number} degrees, <= 0 (0 when metersAboveGround === 0)
     */
    function horizonDipAngle(observer: Observer, metersAboveGround: number): number {
        const phi = observer.latitude * DEG;
        const sinphi = Math.sin(phi);
        const cosphi = Math.cos(phi);
        const c = 1 / Math.hypot(cosphi, sinphi * EARTH_FLATTENING);
        const s = c * (EARTH_FLATTENING * EARTH_FLATTENING);
        const ht_km = (observer.height - metersAboveGround) / 1000;
        const ach = EARTH_EQUATORIAL_RADIUS_KM * c + ht_km;
        const ash = EARTH_EQUATORIAL_RADIUS_KM * s + ht_km;
        const radius_m = 1000 * Math.hypot(ach * cosphi, ash * sinphi);
        const k = 0.175 * Math.pow(
            1 - (6.5e-3 / 283.15) * (observer.height - (2 / 3) * metersAboveGround), 3.256);
        return RAD * -(Math.sqrt(2 * (1 - k) * metersAboveGround / radius_m) / (1 - k));
    }

    /**
     * The altitude of the (unrefracted, geometric) horizon that a body's highest
     * point must cross for rise/set, in degrees. This is exactly the quantity
     * `SearchRiseSet()` computes internally:
     *
     *     target = dip(observer, metersAboveGround)
     *              − (34/60) · airDensity(groundElevation)
     *
     * `dip` is already negative, and the refraction term lifts the apparent body
     * by 34′ scaled by the relative air density at ground level.
     *
     * Exposed separately so a caller can swap in a different refraction model
     * (Daniel Glauberman's per-location temperature model, for instance) via
     * `opts.horizonTarget`.
     *
     * @param {AstronomyImp.Observer} observer
     * @param {number} [metersAboveGround=0]
     * @returns {number} degrees (negative)
     */
    function horizonTarget(observer: AstronomyImp.Observer, metersAboveGround: number = 0): number {
        if (!Number.isFinite(metersAboveGround) || metersAboveGround < 0)
            throw new Error(`Invalid value for metersAboveGround: ${metersAboveGround}`);
        const atmos = Astronomy.Atmosphere(observer.height - metersAboveGround);
        const dip = horizonDipAngle(observer, metersAboveGround);
        return dip - REFRACTION_NEAR_HORIZON * atmos.density;
    }

    // --------------------------------------------------------------- geometry

    /**
     * @param {AstronomyImp.Vector} a
     * @param {AstronomyImp.Vector} b
     */
    function sub(a: AstronomyImp.Vector, b: AstronomyImp.Vector) { return [a.x - b.x, a.y - b.y, a.z - b.z]; }
    /**
     * @param {number[]} a
     * @param {number[]} b
     */
    function dot(a: number[], b: number[]) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    /**
     * @param {number[]} a
     */
    function norm(a: number[]) { return Math.hypot(a[0], a[1], a[2]); }

    /**
     * Everything needed to place the Moon's lit limb relative to the horizon at
     * one instant.
     *
     * `altCenterDeg` is the UNREFRACTED topocentric altitude of the Moon's
     * centre — `Equator(Moon, t, observer, ofdate=true, aberration=true)` fed to
     * `Horizon()` with no refraction, i.e. bit-for-bit what SearchRiseSet uses.
     * (For the Moon the aberration flag is a no-op: `GeoVector(Body.Moon, ...)`
     * returns `GeoMoon()` regardless.)
     *
     * `phaseAngleDeg` is TOPOCENTRIC: the angle at the Moon's centre between the
     * direction to the Sun and the direction to the observer, straight from the
     * vectors. `phaseAngleGeoDeg` is the library's geocentric
     * `Illumination().phase_angle`, returned only for comparison — the two
     * differ by up to ~1° near new moon and it is the topocentric one that
     * shapes the terminator an observer actually sees.
     *
     * TWO h VALUES are returned. `h` is PLAN.md's flat-disk closed form; `hExact`
     * additionally accounts for the fact that the visible cap stops at
     * n·ê3 = sin ρ rather than 0 and for the perspective magnification of
     * near-side points. They agree to ~2 arcsec for phase angles up to 120°;
     * `hExact` is the one that matches the brute-force oracle at every phase
     * (to <0.1"), and it is the one the 'lit' search mode uses.
     *
     * @param {FlexibleDateTime} time
     * @param {AstronomyImp.Observer} observer
     * @returns {MoonGeometry}
     * }}
     */
    function moonGeometry(time: FlexibleDateTime, observer: AstronomyImp.Observer): MoonGeometry {
        const t = Astronomy.MakeTime(time);

        const eqMoon = Astronomy.Equator(Body.Moon, t, observer, true, true);
        const hor = Astronomy.Horizon(t, observer, eqMoon.ra, eqMoon.dec);  // no refraction
        const semiDiameterDeg = RAD * Math.asin(MOON_RADIUS_AU / eqMoon.dist);

        const eqSun = Astronomy.Equator(Body.Sun, t, observer, true, true);

        // Local hour angle, same definition as Astronomy.HourAngle() but reusing
        // the RA we already have instead of recomputing the Moon's position.
        const gast = Astronomy.SiderealTime(t);
        let haHours = (observer.longitude / 15 + gast - eqMoon.ra) % 24;
        if (haHours < 0) haHours += 24;
        const hourAngleDeg = haHours * 15;

        const chiDeg = brightLimbPositionAngle(eqSun.ra, eqSun.dec, eqMoon.ra, eqMoon.dec);
        const qDeg = parallacticAngle(hourAngleDeg, observer.latitude, eqMoon.dec);
        const thetaDeg = limbAngleFromVertical(chiDeg, qDeg);

        // Topocentric phase angle straight from the vectors.
        const moonG = Astronomy.GeoVector(Body.Moon, t, true);
        const sunG = Astronomy.GeoVector(Body.Sun, t, true);
        const obsV = Astronomy.ObserverVector(t, observer, false);
        const toSun = sub(sunG, moonG);
        const toObs = sub(obsV, moonG);
        let cosPhase = dot(toSun, toObs) / (norm(toSun) * norm(toObs));
        if (cosPhase > 1) cosPhase = 1; else if (cosPhase < -1) cosPhase = -1;
        const phaseAngleDeg = RAD * Math.acos(cosPhase);

        const illum = Astronomy.Illumination(Body.Moon, t);

        return {
            time: t,
            altCenterDeg: hor.altitude,
            azDeg: hor.azimuth,
            distTopoKm: eqMoon.dist * Astronomy.KM_PER_AU,
            semiDiameterDeg,
            raMoonHours: eqMoon.ra,
            decMoonDeg: eqMoon.dec,
            hourAngleDeg,
            phaseAngleDeg,
            phaseAngleGeoDeg: illum.phase_angle,
            chiDeg,
            qDeg,
            thetaDeg,
            h: highestLitPointFactor(thetaDeg, phaseAngleDeg),
            hExact: highestLitPointFactor3D(thetaDeg, phaseAngleDeg, semiDiameterDeg),
            litFraction: litDiskAreaFraction(phaseAngleDeg),
            litFractionGeo: illum.phase_fraction
        };
    }

    const MODES = ['lit', 'lit-flat', 'geometric'];

    /**
     * @param {'lit'|'lit-flat'|'geometric'} mode
     */
    function checkMode(mode: 'lit' | 'lit-flat' | 'geometric') {
        if (!MODES.includes(mode)) throw new Error(`Invalid mode: ${mode}`);
        return mode;
    }

    /**
     * Fast path used inside the root finder: altitude of the relevant highest
     * point, without the bits of `moonGeometry()` that cost an extra ephemeris
     * evaluation but are not needed.
     *
     * @param {AstronomyImp.AstroTime} t
     * @param {AstronomyImp.Observer} observer
     * @param {'lit'|'lit-flat'|'geometric'} mode
     * @returns {number} altitude in degrees
     */
    function topAltitude(t: AstronomyImp.AstroTime, observer: AstronomyImp.Observer, mode: 'lit' | 'lit-flat' | 'geometric'): number {
        const eqMoon = Astronomy.Equator(Body.Moon, t, observer, true, true);
        const hor = Astronomy.Horizon(t, observer, eqMoon.ra, eqMoon.dec);
        const semi = RAD * Math.asin(MOON_RADIUS_AU / eqMoon.dist);
        if (mode === 'geometric') return hor.altitude + semi;

        const eqSun = Astronomy.Equator(Body.Sun, t, observer, true, true);
        const gast = Astronomy.SiderealTime(t);
        let haHours = (observer.longitude / 15 + gast - eqMoon.ra) % 24;
        if (haHours < 0) haHours += 24;
        const chi = brightLimbPositionAngle(eqSun.ra, eqSun.dec, eqMoon.ra, eqMoon.dec);
        const q = parallacticAngle(haHours * 15, observer.latitude, eqMoon.dec);
        const theta = limbAngleFromVertical(chi, q);

        const moonG = Astronomy.GeoVector(Body.Moon, t, true);
        const sunG = Astronomy.GeoVector(Body.Sun, t, true);
        const obsV = Astronomy.ObserverVector(t, observer, false);
        const toSun = sub(sunG, moonG);
        const toObs = sub(obsV, moonG);
        let cosPhase = dot(toSun, toObs) / (norm(toSun) * norm(toObs));
        if (cosPhase > 1) cosPhase = 1; else if (cosPhase < -1) cosPhase = -1;
        const i = RAD * Math.acos(cosPhase);

        const h = (mode === 'lit-flat')
            ? highestLitPointFactor(theta, i)
            : highestLitPointFactor3D(theta, i, semi);
        return hor.altitude + h * semi;
    }

    /**
     * How far the Moon's highest relevant point is above the horizon target,
     * in degrees. Zero exactly at rise/set.
     *
     *   excess = altCenter + h · semiDiameter − horizonTarget
     *
     * @param {FlexibleDateTime} time
     * @param {AstronomyImp.Observer} observer
     * @param {LitLimbAltitudeExcessOptions} [opts]
     * @returns {number} degrees
     */
    function litLimbAltitudeExcess(time: FlexibleDateTime, observer: AstronomyImp.Observer, opts: LitLimbAltitudeExcessOptions = {}): number {
        const mode = checkMode(opts.mode || 'lit');
        const meters = opts.metersAboveGround ?? 0;
        const targetFn = opts.horizonTarget || horizonTarget;
        const target = targetFn(observer, meters);
        const t = Astronomy.MakeTime(time);
        return topAltitude(t, observer, mode) - target;
    }

    // ----------------------------------------------------------------- search

    /**
     * Maximum possible rate of change of the Moon's topocentric altitude,
     * degrees/day, for the pruning test in the ascent finder. Same experimental
     * bounds the library uses (d(RA)/dt ≥ +4.5°/d, |d(Dec)/dt| ≤ 8.2°/d).
     * @param {number} latitude
     */
    function maxAltitudeSlope(latitude: number) {
        if (latitude < -90 || latitude > 90)
            throw new Error(`Invalid geographic latitude: ${latitude}`);
        const deriv_ra = +4.5, deriv_dec = +8.2;
        const latrad = latitude * DEG;
        return Math.abs(((360 / SOLAR_DAYS_PER_SIDEREAL_DAY) - deriv_ra) * Math.cos(latrad))
            + Math.abs(deriv_dec * Math.sin(latrad));
    }

    /**
     * Recursive bisection that hunts for a sub-interval where `altdiff` rises
     * through zero. Same algorithm as astronomy.js's private `FindAscent()`.
     * @param {number} depth
     * @param {{ (t: any): number; (arg0: AstronomyImp.AstroTime): any; }} altdiff
     * @param {number} maxDeriv
     * @param {AstronomyImp.AstroTime} t1
     * @param {AstronomyImp.AstroTime} t2
     * @param {number} a1
     * @param {number} a2
     */
    function findAscent(depth: number, altdiff: { (t: any): number; (arg0: AstronomyImp.AstroTime): any; }, maxDeriv: number, t1: AstronomyImp.AstroTime, t2: AstronomyImp.AstroTime, a1: number, a2: number) {
        if (a1 < 0 && a2 >= 0) return { tx: t1, ty: t2, ax: a1, ay: a2 };
        if (a1 >= 0 && a2 < 0) return null;
        if (depth > 17) throw new Error('Excessive recursion in rise/set ascent search.');
        const dt = t2.ut - t1.ut;
        if (dt * SECONDS_PER_DAY < 1) return null;
        const da = Math.min(Math.abs(a1), Math.abs(a2));
        if (da > maxDeriv * (dt / 2)) return null;
        const tmid = Astronomy.MakeTime((t1.ut + t2.ut) / 2);
        const amid = altdiff(tmid);
        return findAscent(1 + depth, altdiff, maxDeriv, t1, tmid, a1, amid)
            || findAscent(1 + depth, altdiff, maxDeriv, tmid, t2, amid, a2);
    }

    /**
     * Next moonrise or moonset after `startTime`.
     *
     * TIME STEPPING — why 0.42 day and not "≤ 5 minutes":
     * a fixed small step is both slower and *less* safe than what the library
     * does. The coarse 0.42-day window (10.08 h, Nyquist-safe against the Moon's
     * ~22 h up/down cycle even at extreme lunar declination) is handed to a
     * recursive bisection that keeps splitting the interval unless the altitude
     * PROVABLY cannot reach zero and come back: if min(|a1|,|a2|) exceeds
     * maxAltitudeSlope · dt/2 the sub-interval is pruned, otherwise it is split,
     * down to a 1-second floor. That catches the high-latitude grazing case
     * where a rise and set are minutes apart — which a uniform 5-minute scan can
     * still straddle — and it is the same scheme SearchRiseSet uses, which is
     * what makes 'geometric' mode reproduce the library to well under a second.
     *
     * In 'lit' mode the altitude of the highest lit point also moves because h
     * moves; |d(h·R)/dt| ≤ R · |dθ/dt| ≲ 0.26° · 2π rad/day ≈ 1.7°/day, so the
     * slope bound gets a 5°/day safety margin (a larger bound only prunes less,
     * never more, so it cannot cause a miss).
     *
     * @param {number} direction  +1 = rise, −1 = set
     * @param {FlexibleDateTime} startTime
     * @param {AstronomyImp.Observer} observer
     * @param {NextMoonEventOptions} [opts]
     * @returns {AstronomyImp.AstroTime|null} AstroTime, or null if no such event in the window
     */
    function nextMoonEvent(direction: number, startTime: FlexibleDateTime, observer: AstronomyImp.Observer, opts: NextMoonEventOptions = {}): AstronomyImp.AstroTime | null {
        if (direction !== +1 && direction !== -1)
            throw new Error(`Invalid direction: ${direction} (must be +1 or -1)`);
        const mode = checkMode(opts.mode || 'lit');
        const limitDays = opts.limitDays ?? 2;
        const meters = opts.metersAboveGround ?? 0;
        const targetFn = opts.horizonTarget || horizonTarget;
        const target = targetFn(observer, meters);

        const maxDeriv = maxAltitudeSlope(observer.latitude) + (mode === 'geometric' ? 0 : 5);
        const altdiff = (/** @type {AstronomyImp.AstroTime} */ t: AstronomyImp.AstroTime) => direction * (topAltitude(t, observer, mode) - target);

        const startTimeT = Astronomy.MakeTime(startTime);
        let t1 = startTimeT, t2 = startTimeT;
        let a1 = altdiff(t1), a2 = a1;

        for (;;) {
            if (limitDays < 0) {
                t1 = t2.AddDays(-RISE_SET_DT);
                a1 = altdiff(t1);
            } else {
                t2 = t1.AddDays(+RISE_SET_DT);
                a2 = altdiff(t2);
            }
            const ascent = findAscent(0, altdiff, maxDeriv, t1, t2, a1, a2);
            if (ascent) {
                const time = Astronomy.Search(altdiff, ascent.tx, ascent.ty, {
                    dt_tolerance_seconds: 0.1,
                    init_f1: ascent.ax,
                    init_f2: ascent.ay
                });
                if (time) {
                    if (limitDays < 0) {
                        if (time.ut < startTimeT.ut + limitDays) return null;
                    } else {
                        if (time.ut > startTimeT.ut + limitDays) return null;
                    }
                    return time;
                }
                throw new Error('Rise/set search failed after finding ascent.');
            }
            if (limitDays < 0) {
                if (t1.ut < startTimeT.ut + limitDays) return null;
                t2 = t1; a2 = a1;
            } else {
                if (t2.ut > startTimeT.ut + limitDays) return null;
                t1 = t2; a1 = a2;
            }
        }
    }

    /**
     * Next moonrise after `startTime`.
     * @param {FlexibleDateTime} startTime
     * @param {AstronomyImp.Observer} observer
     * @param {NextMoonEventOptions} [opts]
     * @returns {AstronomyImp.AstroTime|null}
     */
    function nextMoonRise(startTime: FlexibleDateTime, observer: AstronomyImp.Observer, opts: NextMoonEventOptions = {}): AstronomyImp.AstroTime | null {
        return nextMoonEvent(+1, startTime, observer, opts);
    }

    /**
     * Next moonset after `startTime`.
     * @param {FlexibleDateTime} startTime
     * @param {AstronomyImp.Observer} observer
     * @param {NextMoonEventOptions} [opts]
     * @returns {AstronomyImp.AstroTime|null}
     */
    function nextMoonSet(startTime: FlexibleDateTime, observer: AstronomyImp.Observer, opts: NextMoonEventOptions = {}): AstronomyImp.AstroTime | null {
        return nextMoonEvent(-1, startTime, observer, opts);
    }

    /**
     * Rise and set inside the 24 hours starting at `localMidnight` (which the
     * caller supplies as an instant — this function has no notion of a time
     * zone, deliberately: the day boundary is whatever instant you hand it).
     *
     * @param {FlexibleDateTime} localMidnight
     * @param {Observer} observer
     * @param {MoonEventsForDayOptions} [opts]
     * @returns {MoonEventsForDay}
     */
    function moonEventsForDay(localMidnight: FlexibleDateTime, observer: Observer, opts: MoonEventsForDayOptions = {}): MoonEventsForDay {
        const t0 = Astronomy.MakeTime(localMidnight);
        const litMode = checkMode(opts.mode || 'lit');
        if (litMode === 'geometric')
            throw new Error("moonEventsForDay: mode must be 'lit' or 'lit-flat'");
        const base = { ...opts, limitDays: 1 };
        const out:Partial<MoonEventsForDay> = {};
        for (const [name, direction] of [['rise', +1], ['set', -1]]) {
            const intDir = typeof direction == "string" ? parseInt(direction) : direction;

            const geometric = nextMoonEvent(intDir, t0, observer, { ...base, mode: 'geometric' });
            const lit = nextMoonEvent(intDir, t0, observer, { ...base, mode: litMode });
            out[name as 'rise'|'set'] = {
                lit,
                geometric,
                correctionSeconds: (lit && geometric)
                    ? (lit.ut - geometric.ut) * SECONDS_PER_DAY
                    : null
            };
        }
        return out as MoonEventsForDay;
    }

    return {
        horizonDipAngle,
        horizonTarget,
        moonGeometry,
        litLimbAltitudeExcess,
        nextMoonEvent,
        nextMoonRise,
        nextMoonSet,
        moonEventsForDay,
        // re-exported for convenience so callers need only one import
        litFractionAboveLine,
        highestLitPointFactor,
        highestLitPointFactor3D,
        MOON_EQUATORIAL_RADIUS_KM,
        RISE_SET_DT
    };
}
